import assert from'node:assert/strict';
import * as core from'@nautilus-engine/core/tiles';
import * as T from'@nautilus-engine/renderer/render-effects/three';
import{prepareTileArt}from'@nautilus-engine/tile-visuals-candidate';
import{createTileArtProvider}from'@nautilus-engine/tile-visuals-candidate/three';
import{boundaryMaterialProof}from'./boundary-material-proof.mjs';
import{inputGradeProof}from'./input-grade-proof.mjs';
import{tileLifecycleProof}from'./lifecycle-proof.mjs';
import{canonicalTileArtExample,surfaceRecipe,binaryFieldRecipe,pathRecipe,tileArtBundle,tileArtTransforms}from'@nautilus-engine/tile-visuals-candidate/example';
assert.equal(core.TILE_CONTRACT.registration.startsWith('declared'),true);assert.equal(globalThis.document,undefined);
const bundle=canonicalTileArtExample(core),saved=JSON.stringify(bundle),opened=core.openTileBundle(saved,{requireResolved:true}),projection=JSON.parse(JSON.stringify(prepareTileArt(core,opened.bundle,{detailsByInstance:{'paving-a':0,'paving-b':2}}))),material=new T.MeshStandardMaterial({vertexColors:true});let borrowedDisposals=0;material.addEventListener('dispose',()=>borrowedDisposals++);
const view=createTileArtProvider(T,projection,{materialForInstance:()=>material,profileBindings:projection.entries.flatMap(e=>e.inspected.ports.map(p=>({profiles:p.profiles,boundaryMaterial:p.geometry.materialIntervals[0].material,material})))}),scene=new T.Scene(),sentinel=new T.Group();scene.add(sentinel,view.root);let samples=0;
try{for(const p of view.interfaces){assert.ok(p.geometry instanceof T.BufferGeometry);const surfaces=view.root.children.find(g=>g.name==='tile:'+p.instanceId).children.filter(m=>m.userData.role==='canonical-surface');for(let i=0;i<p.geometry.attributes.position.count;i++){const expected=['position','normal','uv'].flatMap(k=>Array.from({length:k==='uv'?2:3},(_,j)=>p.geometry.attributes[k].array[i*(k==='uv'?2:3)+j]));assert.ok(surfaces.some(m=>{const a=m.geometry.attributes;for(let j=0;j<a.position.count;j++){const actual=['position','normal','uv'].flatMap(k=>Array.from({length:k==='uv'?2:3},(_,n)=>a[k].array[j*(k==='uv'?2:3)+n]));if(actual.every((v,n)=>v===expected[n]))return true;}return false;}));samples++;}}
assert.equal(projection.bundle.recipes.find(r=>r.id==='path').shape.path.points[1][0],2.123456789);assert.equal(JSON.stringify(bundle),saved);assert.equal(view.statuses.gameplay.support,'unbound');view.setResident(['paving-b']);const border=view.interfaces.find(p=>p.instanceId==='paving-b').geometry.attributes.position.array.slice();view.removeInstance('paving-a');assert.deepEqual(view.interfaces.find(p=>p.instanceId==='paving-b').geometry.attributes.position.array,border);
}finally{view.dispose();view.dispose();assert.deepEqual(scene.children,[sentinel]);assert.equal(borrowedDisposals,0);material.dispose();}
const api={prepareTileArt,createTileArtProvider},fixtures={surfaceRecipe,binaryFieldRecipe,pathRecipe,tileArtBundle,tileArtTransforms},materialReview=boundaryMaterialProof(core,T,api,fixtures),inputReview=inputGradeProof(core,T,api,fixtures);assert.equal(materialReview.status,'pass',JSON.stringify(materialReview.failures));assert.equal(inputReview.status,'pass',JSON.stringify(inputReview));
const lifecycle=tileLifecycleProof(core,T,api,{...fixtures,canonicalTileArtExample});
console.log(JSON.stringify({status:'pass',actualDeclaredCore:true,lifecycle,materialBindingCases:materialReview.cases.length,materialEdgesChecked:materialReview.edgesChecked,accessorCases:inputReview.getters.length,prototypeIdCases:inputReview.instanceIds.length,authoredGradeCases:inputReview.grades.length,coreContract:core.TILE_CONTRACT.version,threeRevision:T.REVISION,canonicalSamplesReferenced:samples,sourceControlsRetained:true,canonicalBundleReopened:true,neighborSurvivedRemoval:true,borrowedResourcesPreserved:true,privateProvider:true,scope:'Native flat surfaces; body/support/game adoption unbound'}));
